-- Keep existing desktop scripts compatible with the 0.57 Lua IPC API.
local local_bin = os.getenv("HOME") .. "/.local/bin"
local path_parts = { local_bin }
for part in os.getenv("PATH"):gmatch("[^:]+") do
    if part ~= local_bin then table.insert(path_parts, part) end
end
hl.env("PATH", table.concat(path_parts, ":"))
-- Migrated from hyprland.conf for Hyprland 0.57 (2026-11-02).
-- This Lua file is the active config; the .conf file is retained as a reference.
