-- This is an example Hyprland config file.
-- Refer to the wiki for more information.
-- https://wiki.hyprland.org/Configuring/

-- Please note not all available settings / options are set here.
-- For a full list, see the wiki

-- You can split this configuration into multiple files
-- Create your files separately and then link them to this file like this:
-- source = ~/.config/hypr/myColors.conf

-- Fullscreen-only VRR causes failed DRM commits and 1–2s fullscreen stalls
-- on this display, even with the per-monitor vrr,0 setting below.
hl.config({ ["misc"] = { ["vrr"] = 0 } })

-- Keep fullscreen video from switching monitor profiles/HDR modes. Those
-- DRM modesets can blank the panel for seconds on fullscreen enter/exit.
hl.config({ ["render"] = { ["send_content_type"] = false, ["cm_auto_hdr"] = 0 } })

-- Render XWayland apps at native pixel resolution instead of upscaling (blur fix).
-- XWayland apps must handle their own DPI scaling (e.g. GDK_SCALE=2 for Handy).
hl.config({ ["xwayland"] = { ["force_zero_scaling"] = true } })

--###############
--## MONITORS ###
--###############

-- See https://wiki.hyprland.org/Configuring/Monitors/
-- monitor=,preferred,auto,auto


--######################
--## STREAM SETTINGS ###
--######################
-- 120Hz native + VRR — panel downclocks when idle, smooth when active.
-- To save more battery, drop to 60Hz (and/or lower resolution).
-- monitor = eDP-1, 1920x1200@60, 0x0, 1.33, vrr, 1
-- vrr,0: kernel 7.1 xe forces a full modeset (black flash) when VRR toggles on
-- fullscreen enter/exit — "fastset requirement not met in vrr.guardband".
-- Revisit on future kernels; vrr,2 was fine on 7.0.x.
hl.monitor({ ["output"] = "eDP-1", ["mode"] = "2880x1920@120", ["position"] = "0x0", ["scale"] = 2, ["vrr"] = 0 })
-- Use 60Hz to save battery (costs cursor smoothness)
-- monitor = eDP-1, 2880x1920@60, 0x0, 2, vrr, 0

-- For streaming, we need to make sure DP-3 which is the
-- Elgato HD60X mirrors my external monitor display
-- Define DP-3 (Target/HD60X) as a separate monitor.
-- The exact position doesn't matter much since wl-mirror will take over,
-- but defining its mode explicitly is safest.
-- monitor = DP-3, 3840x2160@60, 1920x0, 1.5
-- Note, if you move the framework HDMI slot to another
-- port you'll likely need to change DP-3 to something else
hl.monitor({ ["output"] = "DP-3", ["mode"] = "preferred", ["position"] = "auto", ["scale"] = 1.5, ["mirror"] = "DP-5" })

-- Samsung TV docking and fullscreen streams; desktop scaling is managed by kanshi.
hl.monitor({ ["output"] = "desc:Samsung Electric Company QN90D 0x01000E00", ["mode"] = "3840x2160@60", ["position"] = "0x0", ["scale"] = 2.4 })
hl.window_rule({ ["fullscreen"] = true, ["match"] = { ["class"] = "^com\\.moonlight_stream\\.Moonlight$", ["title"] = "^.+ - Moonlight$" } })

-- Ensure that audio when streaming can go to CalDigit dock headphone jack AND stream PC
-- Ensure that audio when streaming can go to Bose Black Tie headphones AND stream PC
-- Start Handy (speech-to-text) hidden in the tray for mod+space dictation.
-- GDK_SCALE=2: Handy is stuck on XWayland (its AppImage forces GDK_BACKEND=x11;
-- on native Wayland the transcription overlay never maps), so with
-- xwayland:force_zero_scaling it must render 2x itself or it's tiny/blurry.
-- Set brightness to 15% on startup

