-- Wallust-generated border colors — disabled. Uncomment to re-enable
-- wallpaper-derived theming and remove the hardcoded col.active_border above.
-- source = ~/.config/hypr/colors-hypr.conf

-- Tabbed window groups. Used for the YouTube webapp: app-mode windows have no
-- tab strip of their own, so several of them are grouped at the compositor
-- level instead, which gives one slot with a tab bar rather than N windows
-- competing for screen space.
hl.config({ ["group"] = { ["col.border_active"] = "rgba(33ccffee)" } })
hl.config({ ["group"] = { ["col.border_inactive"] = "rgba(33333388)" } })

hl.config({ ["group"] = { ["groupbar"] = { ["enabled"] = true } } })
-- Hide the bar when the group holds a single window. This is the native
-- option for it (found in the binary's option table; it is absent from
-- the wiki page), replacing a watcher that toggled groupbar:enabled
-- globally -- that was crude and affected every group, not just this one.
hl.config({ ["group"] = { ["groupbar"] = { ["disable_when_only"] = true } } })
-- The bar can only render a window's title, so ~/scripts/yt-tab-numbers.py
-- sets each tab's document.title to its index over CDP -- that is what
-- makes these read 1, 2, 3. Tiny font, short bar.
hl.config({ ["group"] = { ["groupbar"] = { ["render_titles"] = true } } })
hl.config({ ["group"] = { ["groupbar"] = { ["font_family"] = "JetBrainsMono Nerd Font" } } })
-- 7pt was unreadable. Legibility wins over a couple of pixels; this is
-- still well under the 18px default.
hl.config({ ["group"] = { ["groupbar"] = { ["font_size"] = 11 } } })
hl.config({ ["group"] = { ["groupbar"] = { ["height"] = 15 } } })
hl.config({ ["group"] = { ["groupbar"] = { ["indicator_height"] = 0 } } })
hl.config({ ["group"] = { ["groupbar"] = { ["gaps_in"] = 2 } } })
hl.config({ ["group"] = { ["groupbar"] = { ["gaps_out"] = 2 } } })
hl.config({ ["group"] = { ["groupbar"] = { ["rounding"] = 3 } } })
hl.config({ ["group"] = { ["groupbar"] = { ["keep_upper_gap"] = false } } })
hl.config({ ["group"] = { ["groupbar"] = { ["gradients"] = false } } })

-- Mirrors the waybar workspace indicators: dark ground throughout, the
-- active tab on the same grey pill, its number bright and bold while the
-- rest stay dim. col.active was previously a LIGHT colour with white
-- text on top, which made the numbers unreadable and gave no way to tell
-- which tab was active.
hl.config({ ["group"] = { ["groupbar"] = { ["col.active"] = "rgba(64727dff)" } } })
hl.config({ ["group"] = { ["groupbar"] = { ["col.inactive"] = "rgba(1a1a1acc)" } } })
hl.config({ ["group"] = { ["groupbar"] = { ["text_color"] = "rgba(ffffffff)" } } })
hl.config({ ["group"] = { ["groupbar"] = { ["text_color_inactive"] = "rgba(9a9a9aff)" } } })
-- Named weights only. A numeric 700 is accepted with "ok" and then
-- silently ignored -- the value stays 400.
hl.config({ ["group"] = { ["groupbar"] = { ["font_weight_active"] = "bold" } } })
hl.config({ ["group"] = { ["groupbar"] = { ["font_weight_inactive"] = "normal" } } })
-- stacked = true was tried for vertical tabs: it stacks the entries into
-- a column but keeps the bar at the TOP, so it grows downward one row
-- per tab. There is no option to move the groupbar to a side.
hl.config({ ["group"] = { ["groupbar"] = { ["scrolling"] = true } } })

-- https://wiki.hyprland.org/Configuring/Variables/#decoration
hl.config({ ["decoration"] = { ["rounding"] = 5 } })
hl.config({ ["decoration"] = { ["rounding_power"] = 2 } })

-- Change transparency of focused and unfocused windows
