--## WINDOWS AND WORKSPACES ###
--#############################

-- See https://wiki.hyprland.org/Configuring/Window-Rules/ for more
-- See https://wiki.hyprland.org/Configuring/Workspace-Rules/ for workspace rules

-- Example windowrule
-- windowrule = float,class:^(kitty)$,title:^(kitty)$

-- Ignore maximize requests from apps. You'll probably like this.
hl.window_rule({ ["suppress_event"] = "maximize", ["match"] = { ["class"] = ".*" } })

-- Fix some dragging issues with XWayland
hl.window_rule({ ["no_focus"] = true, ["match"] = { ["class"] = "^$", ["title"] = "^$", ["xwayland"] = 1, ["float"] = 1, ["fullscreen"] = 0, ["pin"] = 0 } })

-- Picture-in-Picture mode rules
hl.window_rule({ ["float"] = true, ["pin"] = true, ["keep_aspect_ratio"] = true, ["size"] = "(monitor_w*0.3) (monitor_h*0.3)", ["move"] = "((monitor_w*0.7)) ((monitor_h*0.7))", ["match"] = { ["title"] = "^(Picture-in-Picture)$" } })

-- MPV PiP mode - small bottom-right corner.
-- The 13 is the gap a tiled window leaves at the screen edge: gaps_out (12) plus
-- border_size (1). The margins used to be proportional (0.6175 / 0.995), which
-- worked out to ~4px and no longer lined up once gaps_out went 10 -> 12, leaving
-- the float overhanging the tiled window's corner by 9px across and 8px down.
-- Update this if gaps_out or border_size change.
-- NOTE write the move() arithmetic WITHOUT spaces. Hyprland 0.56 silently drops
-- the whole rule -- no error, the window just lands wherever the app puts it --
-- when a space-separated operand is a bare number, as in (monitor_w*0.62 - 13).
-- Spaces are tolerated while both operands are monitor-relative, which is why
-- the older (monitor_h*0.995 - monitor_w*0.21375) form worked. Measured all
-- three against a throwaway window: bare-number-spaced landed at [648,341],
-- the other two on target.
-- Height is derived from width*9/16 so the float is 16:9 on any monitor
-- aspect (laptop 3:2 vs LG 16:9). Required so panscan=1.0 from
-- twitch-launcher.sh has nothing to crop when the float is the active mpv window.
hl.window_rule({ ["float"] = true, ["size"] = "(monitor_w*0.38) (monitor_w*0.21375)", ["move"] = "(monitor_w*0.62-13) (monitor_h-monitor_w*0.21375-13)", ["keep_aspect_ratio"] = true, ["no_initial_focus"] = true, ["animation"] = "slide right", ["match"] = { ["class"] = "^(mpv)$" } })

-- Pinned MPV accepts hover/click focus so its normal playback keys work.
-- no_initial_focus above still prevents a newly opened player stealing focus.

-- Handy live-transcription overlay - bottom center, never focused.
-- no_focus is required: if the overlay takes focus, Handy pastes the
-- transcript into the overlay instead of the window you were dictating into.
-- Overlay is 400x200 @ GDK_SCALE=2 = 800x400 px; with xwayland force_zero_scaling
-- its logical size is 800/scale x 400/scale, hence the monitor_scale math.
-- NB: no spaces inside move () exprs — the parser silently drops the rule with them.
hl.window_rule({ ["float"] = true, ["pin"] = true, ["no_focus"] = true, ["no_initial_focus"] = true, ["move"] = "(monitor_w*0.5-400/monitor_scale) (monitor_h-20-400/monitor_scale)", ["match"] = { ["class"] = "^(Handy)$", ["title"] = "^(Recording)$" } })
-- Strip all decorations so only the transcription text is visible: no border,
-- shadow, rounding, or animation, and opaque off overrides the blanket
-- "opaque on [Hh]andy" rule above (which turns the transparent bg into a solid box).
hl.window_rule({ ["border_size"] = 0, ["no_shadow"] = true, ["rounding"] = 0, ["no_anim"] = true, ["no_dim"] = true, ["opaque"] = false, ["match"] = { ["class"] = "^(Handy)$", ["title"] = "^(Recording)$" } })

-- Discord Popout - small bottom-right corner (UNCHANGED)
hl.window_rule({ ["float"] = true, ["pin"] = true, ["keep_aspect_ratio"] = true, ["size"] = "(monitor_w*0.3) (monitor_h*0.3)", ["move"] = "((monitor_w*0.7)) ((monitor_h*0.7))", ["match"] = { ["title"] = "^(vesktop)$" } })


-- Be able to pin and unpin videos like mpv to play in
-- picture in picture and persist across workspaces
-- but also be able to unpin to fullscreen
hl.bind("Alt + P", hl.dsp.exec_cmd("~/scripts/toggle-pip-set.sh"))
-- Picture-in-picture toggle for the YouTube webapp.
--
-- Drives Chromium's native video context menu (shift+right-click -> the
-- "Picture in picture" item) because neither shortcut route works:
--   - Extension commands do not fire in Chromium app-mode windows at all.
--     Verified with two extensions; the same synthetic keys DO trigger them
--     in a normal Brave window.
--   - Chromium ships no built-in PiP keybinding.
-- The script uses ydotool rather than wtype because PiP needs a genuine user
-- gesture: wtype moved the menu highlight fine but Enter never activated it.
hl.bind("Alt + SHIFT + 9", hl.dsp.exec_cmd("~/scripts/yt-pip-toggle.sh"))
-- Open a copied YouTube link in the webapp. App-mode windows have no address
-- bar, so a link cannot be pasted in the normal way; this navigates the
-- running window over CDP (same session, no second window), or launches the
-- webapp on that URL if it is not open.
--
-- V for Video. Freed up by moving pavucontrol to the waybar speaker icon.
hl.bind("Alt + SHIFT + V", hl.dsp.exec_cmd("~/scripts/yt-open.sh"))
-- Cycle tabs within a window group, on Ctrl+Tab / Ctrl+Shift+Tab to match
-- Brave's own tab switching. Fn cannot be
-- used: only ydotool's virtual device advertises KEY_FN, so Fn is handled in
-- the Framework's firmware and never reaches the compositor.
--
-- Bind the physical Tab key once per direction. Shift changes its keysym to
-- ISO_Left_Tab; overlapping Tab and ISO_Left_Tab binds can both match a press.
-- Via a script, not changegroupactive directly: Hyprland binds are global, so
-- binding this key here took Ctrl+Tab away from every other window -- ordinary
-- Brave could no longer switch its own tabs. The script cycles the group when
-- the focused window is a tab group and forwards the key to the application
-- otherwise.
hl.bind("CTRL + code:23", hl.dsp.exec_cmd("~/scripts/yt-tab-cycle.sh f"))
hl.bind("CTRL + SHIFT + code:23", hl.dsp.exec_cmd("~/scripts/yt-tab-cycle.sh b"))
-- Kept as an alternative; Super has no other bindings.
hl.bind("SUPER + Tab", hl.dsp.group.next())
hl.bind("SUPER + SHIFT + Tab", hl.dsp.group.prev())
-- Playback speed for the YouTube webapp, mirroring the mpv muscle memory
-- (mpv: "}" = 2x, and Shift+) resets speed to 1 as part of its reset bind).
-- Super+Shift+0 is taken by the password manager, so [ and ] pair up here.
-- Setting playbackRate on the video element carries into the PiP window,
-- since PiP renders that same element rather than a copy.
-- Physical bracket keys avoid shifted/unshifted keysym ambiguity and duplicate
-- dispatches. CDP controls the playing/PiP video without changing window focus.
hl.bind("Alt + SHIFT + code:35", hl.dsp.exec_cmd("~/scripts/yt-pip-cdp.py --rate 2"))
hl.bind("Alt + SHIFT + code:34", hl.dsp.exec_cmd("~/scripts/yt-pip-cdp.py --rate 1"))
-- bind = $mainMod, C, exec, /home/knaught/scripts/toggle-chat-visibility.sh

-- --- WINDOW RULE: Send Chatterino to the special workspace ---
-- The 'silent' parameter ensures Hyprland doesn't switch focus to the
-- special workspace when Chatterino first launches.
-- Sits flush against the left edge of the PiP float with its bottom on the same
-- line, so the two read as one strip. 0.52 = the float's 0.62 minus this window's
-- own 0.1 width; the -13 is the same gaps_out + border_size margin the float uses.
-- Moves whenever the PiP rules move.
hl.window_rule({ ["workspace"] = "special:chatterino_chat silent", ["float"] = true, ["size"] = "(monitor_w*0.1) (monitor_w*0.21375)", ["move"] = "(monitor_w*0.52-13) (monitor_h-monitor_w*0.21375-13)", ["no_initial_focus"] = true, ["animation"] = "slide right", ["match"] = { ["class"] = "^(com.chatterino.chatterino)$" } })
hl.window_rule({ ["workspace"] = "special:chatterino_chat silent", ["float"] = true, ["size"] = "(monitor_w*0.1) (monitor_w*0.21375)", ["move"] = "(monitor_w*0.52-13) (monitor_h-monitor_w*0.21375-13)", ["no_initial_focus"] = true, ["animation"] = "slide right", ["match"] = { ["class"] = "^newsboat-live-chat$" } })
-- Keep live chats beside the player; YouTube needs extra room for messages.
hl.window_rule({ ["size"] = "(monitor_w*0.125) (monitor_w*0.21375)", ["move"] = "(monitor_w*0.495-13) (monitor_h-monitor_w*0.21375-13)", ["match"] = { ["class"] = "^newsboat-live-chat$", ["title"] = "^Kick live chat$" } })
hl.window_rule({ ["size"] = "(monitor_w*0.25) (monitor_w*0.21375)", ["move"] = "(monitor_w*0.37-13) (monitor_h-monitor_w*0.21375-13)", ["match"] = { ["class"] = "^newsboat-live-chat$", ["title"] = "^You[Tt]ube live chat$" } })
-- Give YouTube comments more reading room, keeping the same right/bottom edges.
hl.window_rule({ ["workspace"] = "special:chatterino_chat silent", ["float"] = true, ["size"] = "(monitor_w*0.2) (monitor_w*0.21375)", ["move"] = "(monitor_w*0.42-13) (monitor_h-monitor_w*0.21375-13)", ["no_initial_focus"] = true, ["animation"] = "slide right", ["match"] = { ["class"] = "^newsboat-youtube-comments$" } })
hl.window_rule({ ["opaque"] = true, ["match"] = { ["class"] = "(.*)(chatterino)(.*)" } })
hl.window_rule({ ["opaque"] = true, ["match"] = { ["class"] = "^newsboat-youtube-comments$" } })
hl.window_rule({ ["opaque"] = true, ["match"] = { ["class"] = "(.*)(bee)(.*)" } })

-- --- WINDOW RULES: Appearance/Positioning (Applies only when visible) ---

-- --- KEYBIND: Launch/Toggle Logic (e.g., SUPER+T for Twitch/Chat) ---
-- We'll use 'chatterino' as the process name for pgrep.
hl.bind("Alt + C", hl.dsp.exec_cmd("python3 $HOME/scripts/media-chat.py"))

-- --- NEWSBOAT ARTICLE POPUP: float + size + center brave --app windows ---
-- Wayland Brave auto-generates class as brave-{host}__-Default per app mode
-- Book readers use the same centered 80% popup layout as Newsboat articles.
hl.window_rule({ ["float"] = true, ["size"] = "(monitor_w*0.8) (monitor_h*0.8)", ["move"] = "(monitor_w*0.1) (monitor_h*0.1)", ["opaque"] = true, ["match"] = { ["class"] = "^(org\\.pwmt\\.zathura|Zathura|com\\.github\\.johnfactotum\\.Foliate)$" } })

-- window. The class regex matches all such windows EXCEPT brave-music.* so
-- the music.youtube.com PWA keeps its tiled behavior. Regex is the manual
-- form since Hyprland's regex doesn't support negative lookahead.
hl.window_rule({ ["float"] = true, ["match"] = { ["class"] = "^brave-(?:[^m]|m[^u]|mu[^s]|mus[^i]|musi[^c]|music[^.]).*-Default$" } })
hl.window_rule({ ["size"] = "(monitor_w*0.8) (monitor_h*0.8)", ["match"] = { ["class"] = "^brave-(?:[^m]|m[^u]|mu[^s]|mus[^i]|musi[^c]|music[^.]).*-Default$" } })
hl.window_rule({ ["move"] = "(monitor_w*0.1) (monitor_h*0.1)", ["match"] = { ["class"] = "^brave-(?:[^m]|m[^u]|mu[^s]|mus[^i]|musi[^c]|music[^.]).*-Default$" } })
hl.window_rule({ ["opaque"] = true, ["match"] = { ["class"] = "^brave-(?:[^m]|m[^u]|mu[^s]|mus[^i]|musi[^c]|music[^.]).*-Default$" } })

-- The float chain above is a hand-rolled "not music." negative match (RE2 has no
-- lookahead), so the YouTube webapp gets swept up in it too. Tile it back here --
-- a later rule wins for the same property.
-- Matches both class forms Chromium produces: the class comes from the launch
-- URL, so opening straight onto a /watch link yields
-- brave-www.youtube.com__watch-Default while the bare homepage yields
-- brave-youtube.com__-Default. The optional www. group covers both and, unlike
-- the old .*youtube.* pattern, does NOT catch the music.youtube.com PWA -- it is a separate app that should stay
-- an ordinary tiled window.
hl.window_rule({ ["float"] = false, ["match"] = { ["class"] = "^brave-(?:www\\.)?youtube\\.com.*-Default$" } })
-- Auto-group the YouTube webapp windows so multiple videos become tabs in
-- one slot instead of N separate windows. App-mode windows have no tab
-- strip of their own.
hl.window_rule({ ["group"] = "set always", ["match"] = { ["class"] = "^brave-(?:www\\.)?youtube\\.com.*-Default$" } })

-- --- SCRATCHPAD: drop-down kitty terminal toggled with SUPER+` ---
-- Spawn on Hyprland startup; dispatcher prefix routes to special workspace
-- and floats; windowrule handles size + centering.
hl.window_rule({ ["size"] = "(monitor_w*0.6) (monitor_h*0.55)", ["match"] = { ["class"] = "^(kitty-scratchpad)$" } })
hl.window_rule({ ["move"] = "(monitor_w*0.2) (monitor_h*0.225)", ["match"] = { ["class"] = "^(kitty-scratchpad)$" } })
hl.window_rule({ ["opaque"] = true, ["match"] = { ["class"] = "^(kitty-scratchpad)$" } })
hl.bind("Alt + grave", hl.dsp.workspace.toggle_special("scratch"))

-- Additional rules for Brave-specific PiP
-- Brave Picture-in-Picture (Allows focus so you can click buttons)
hl.window_rule({ ["float"] = true, ["match"] = { ["title"] = "^(Picture in picture)$" } })
hl.window_rule({ ["pin"] = true, ["match"] = { ["title"] = "^(Picture in picture)$" } })
-- Match Twitch/mpv: 38% of monitor width, with a 16:9 height on either display.
hl.window_rule({ ["size"] = "(monitor_w*0.38) (monitor_w*0.21375)", ["match"] = { ["title"] = "^(Picture in picture)$" } })
-- Lock the float to its 16:9 ratio so manual resizes don't distort the video
hl.window_rule({ ["keep_aspect_ratio"] = true, ["match"] = { ["title"] = "^(Picture in picture)$" } })
-- Same bottom-right corner as the mpv float: 13px in, matching gaps_out (12)
-- plus border_size (1), so it lines up with the tiled window behind it.
hl.window_rule({ ["move"] = "(monitor_w*0.62-13) (monitor_h-monitor_w*0.21375-13)", ["match"] = { ["title"] = "^(Picture in picture)$" } })
hl.window_rule({ ["opaque"] = true, ["match"] = { ["title"] = "^(Picture in picture)$" } })

-- Add this rule for Brave's class-based identification
hl.window_rule({ ["float"] = true, ["pin"] = true, ["match"] = { ["class"] = "^(brave)$", ["title"] = "^(Picture in Picture)$" } })
hl.window_rule({ ["float"] = true, ["no_initial_focus"] = true, ["pin"] = true, ["match"] = { ["title"] = "^(Picture in picture)$" } })
hl.window_rule({ ["no_focus"] = true, ["match"] = { ["class"] = "^(brave).*:^(Picture-in-Picture)$" } })

-- PiP window rules based on exact window properties
-- I do this because I have "Wipeyy" as a chrome/brave browser
-- extension which lets me use hotkeys to control picture in picture
-- For empty class PiP windows
hl.window_rule({ ["no_initial_focus"] = true, ["no_focus"] = true, ["match"] = { ["class"] = "^()$ title:^(Picture in picture)$" } })

-- Dismiss Waybar popups when clicking outside them.
dofile(os.getenv("HOME") .. "/.config/hypr/waybar-panels.lua")

-- Startup runs once at login, not on each config reload.
hl.on("hyprland.start", function()
    hl.exec_cmd("pactl load-module module-combine-sink sink_name=DockStreamAudio slaves=alsa_output.pci-0000_c1_00.1.hdmi-stereo,alsa_output.usb-CalDigit_Inc._CalDigit_TS4_Audio_-_Front-00.analog-stereo")
    hl.exec_cmd("pactl load-module module-combine-sink sink_name=BTStreamAudio slaves=alsa_output.pci-0000_c1_00.1.hdmi-stereo,bluez_output.60_AB_D2_29_C2_2A.1")
    -- Temporarily disabled for Hex trial: hl.exec_cmd("env GDK_SCALE=2 handy --start-hidden")
    -- Start dictation explicitly; this session does not run XDG autostart.
    hl.exec_cmd("/usr/bin/hex start")
    hl.exec_cmd("brightnessctl set 40%")
    hl.exec_cmd("~/scripts/update-timezone.sh")
    hl.exec_cmd("hyprpaper")
    hl.exec_cmd("swaync")
    hl.exec_cmd("~/scripts/yt-tab-watch.sh")
    hl.exec_cmd("~/scripts/hyprland-services-start.sh")
    hl.exec_cmd("~/scripts/restore-pip-position.sh")
    hl.exec_cmd("~/scripts/load-pip-workspace-focus.sh")
    hl.exec_cmd("~/scripts/media-chat-follow.py")
    hl.exec_cmd("~/scripts/workspace-hotplug.py --watch")
    hl.exec_cmd("systemctl --user start swayosd-server")
    hl.exec_cmd("bluetoothctl power on")
    hl.exec_cmd("lspci")
    hl.exec_cmd("sh -c 'd=$HOME/.cache/hyprland; mv -f $d/session.log $d/session.prev.log 2>/dev/null; exec tail -F -n +1 \"$XDG_RUNTIME_DIR/hypr/$HYPRLAND_INSTANCE_SIGNATURE/hyprland.log\" > $d/session.log'")
    hl.exec_cmd("wl-paste -t text --watch clipman store")
    hl.exec_cmd("kitty --class kitty-scratchpad", { workspace = "special:scratch silent", float = true })
end)
hl.on("hyprland.shutdown", function()
    hl.exec_cmd("systemctl --user stop hyprland-session.target")
end)
